async function createNote() { try { const path = $("newPath").value; let content = `# ${path.replace(/\\.md$/i, "")}\\n\\n`; const template = templatePicker.value; if (template) { const source = await api(`/api/file?path=${encodeURIComponent(template)}`); const date = new Date().toLocaleDateString("en-CA"); content = source.content.replaceAll("{{date}}", date).replaceAll("{{title}}", path.replace(/\\.md$/i, "")); } await api("/api/file", { method: "PUT", body: JSON.stringify({ path, content, expectedHash: null }) }); files = await api("/api/files"); dirty = false; await openNote(path, true); status(template ? `Created ${path} from ${template}.` : `Created ${path}.`); } catch (reason) { error(reason); } }
