async function createPdfAnnotation() { const source = $("pdfPath").value.trim().replaceAll("\\", "/"); if (!source.toLowerCase().endsWith(".pdf") || source.includes("..") || source.startsWith("/")) return status("Enter a safe workspace-relative PDF path."); try { const inventory = await api("/api/workspace-files"); if (!inventory.some((item) => item.path === source && item.extension === ".pdf")) return status("That PDF was not found in the open workspace."); const sidecar = `${source}.annotations.md`; if (files.includes(sidecar)) return openNote(sidecar); const annotation = $("pdfAnnotation").value.trim(); const content = `---\ntype: pdf-annotations\nsource: ${source}\n---\n\n# Annotations â€” ${source.split("/").at(-1)}\n\nOriginal: ![[${source}]]\n\n## Annotation 1\n\n${annotation || "_Add annotation here._"}\n`; await api("/api/file", { method: "PUT", body: JSON.stringify({ path: sidecar, content, expectedHash: null }) }); files = await api("/api/files"); dirty = false; await openNote(sidecar, true); status(`Created portable annotation sidecar without changing ${source}.`); } catch (reason) { error(reason); } }
