function renderPreview() { if (!note) return status("Open a note first."); $("markdownPreview").innerHTML = renderMarkdownPreview($("content").value); document.querySelectorAll("[data-preview-link]").forEach((link) => link.onclick = () => { const target = link.dataset.previewLink.split("#")[0]; const resolved = currentContext?.outgoing?.find((item) => item.target === target && item.status === "resolved"); if (resolved) openNote(resolved.path); else status(`Preview link is unresolved: ${target}`); }); document.querySelectorAll("[data-preview-task-line]").forEach((button) => button.onclick = () => previewTaskChange({ path: note.path, line: Number(button.dataset.previewTaskLine), text: button.dataset.previewTaskText }, true)); document.querySelectorAll("[data-preview-embed]").forEach((button) => button.onclick = () => loadTransclusion(button)); renderMermaidDiagrams(); status("Rendered safe local preview. Scripts and raw HTML are not executed."); }
async function loadTransclusion(button) { const reference = button.dataset.previewEmbed, target = reference.split("#")[0]; const resolved = currentContext?.outgoing?.find((item) => item.target === target && item.status === "resolved"); if (!resolved) return status(`Embedded note is unresolved or is an attachment: ${reference}`); try { const embedded = await api(`/api/file?path=${encodeURIComponent(resolved.path)}`), section = extractTransclusion(embedded.content, reference); const container = document.createElement("section"); container.className = "transclusion"; container.innerHTML = section ? renderMarkdownPreview(section) : `<p>Section or block not found: ${escapeHtml(reference)}</p>`; button.replaceWith(container); status(`Loaded read-only transclusion from ${resolved.path}.`); } catch (reason) { error(reason); } }
