  if (!$('exportMindMap')) { const button = document.createElement('button'); button.id = 'exportMindMap'; button.className = 'secondary'; button.textContent = 'Export SVG'; button.onclick = () => { const source = $('mindMapCanvas').outerHTML; const blob = new Blob([source], { type: 'image/svg+xml' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `${note.path.split('/').at(-1).replace(/\.md$/i, '')}-mindmap.svg`; link.click(); URL.revokeObjectURL(link.href); status('Mind map exported without changing the note.'); }; $('mindMap').querySelector('.mind-map-help').append(button); }
